 /**
  * Post-build tripwire for MCP Apps.
  *
  * The current MCP Apps resource is a packed, self-contained HTML document so
  * it does not depend on cross-origin script execution inside a host sandbox.
  * We also keep a small external template for Lobu's own public app route. Its
  * stable assets use content-derived query versions for rolling deployments.
  */
 import { createHash } from "node:crypto";
 import { readdir, readFile, stat } from "node:fs/promises";

 const MAX_RESOURCE_RESPONSE_BYTES = 450_000;
 const APP_ORIGIN = "https://app.lobu.ai";
 const APP_BASE = `${APP_ORIGIN}/mcp-apps/interaction/`;
 const bundleUrl = new URL(
 	"../dist-mcp-apps/interaction/index.html",
 	import.meta.url,
 );
 const source = await readFile(bundleUrl, "utf8");
 const legacySource = await readFile(
 	new URL("../dist-mcp-apps/interaction/legacy-v2.html", import.meta.url),
 	"utf8",
 );
 const currentResourceSource = legacySource;
 const assetsUrl = new URL(
 	"../dist-mcp-apps/interaction/assets/",
 	import.meta.url,
 );
 const allAssetPaths = (await readdir(assetsUrl))
 	.map((name) => `assets/${name}`)
 	.sort();
 const renderedSource = source
 	.replace("<head>", `<head><base href="${APP_BASE}">`)
 	.replaceAll("__LOBU_MCP_APP_ORIGIN__", APP_ORIGIN);
 const sourceBytes = Buffer.byteLength(renderedSource, "utf8");
 const assetPaths = [
 	...source.matchAll(/(?:src|href)="\.\/(assets\/[^"?#]+)(?:\?v=[^"]+)?"/g),
 ].map((match) => match[1]);
 const versionedAssetReferences = [
 	...source.matchAll(/(?:src|href)="\.\/(assets\/[^"?#]+)\?v=([a-f0-9]{16})"/g),
 ].map((match) => ({ assetPath: match[1], version: match[2] }));
 const cssPaths = assetPaths.filter((assetPath) => assetPath.endsWith(".css"));
 const scriptPaths = assetPaths.filter((assetPath) => assetPath.endsWith(".js"));
 const resourceResponseBytes = Buffer.byteLength(
 	JSON.stringify({
 		jsonrpc: "2.0",
 		id: 1,
 		result: {
 			contents: [
 				{
-					uri: "ui://lobu/interaction/v10.html",
+					uri: "ui://lobu/interaction/v11.html",
 					mimeType: "text/html;profile=mcp-app",
 					text: currentResourceSource,
 					_meta: {
 						ui: {
 							csp: {
 								connectDomains: [],
 								resourceDomains: [],
 								frameDomains: [],
 								baseUriDomains: [],
 							},
 							permissions: { clipboardWrite: {} },
 							prefersBorder: true,
 						},
 					},
 				},
 			],
 		},
 	}),
 	"utf8",
 );
 const requiredStoredTemplateSelectors = [
 	".space-y-3",
 	".gap-4",
 	".pr-4",
 	".pt-6",
 	".grid-cols-\\[repeat\\(auto-fill\\,minmax\\(200px\\,1fr\\)\\)\\]",
 ];

 const errors = [];
 if (
 	!legacySource.includes('name="lobu-mcp-packing"') ||
 	!legacySource.includes("gzip-base64-self-contained") ||
 	!legacySource.includes("DecompressionStream") ||
 	!legacySource.includes("pako.ungzip")
 ) {
 	errors.push("self-contained MCP App template is incomplete");
 }
 if (
 	legacySource.includes("__LOBU_MCP_APP_ORIGIN__") ||
 	/(?:src|href)=["'](?:\.\/|\/)?assets\//.test(legacySource)
 ) {
 	errors.push("legacy v2 template still depends on external assets");
 }
 if (!source.includes("__LOBU_MCP_APP_ORIGIN__")) {
 	errors.push("dynamic MCP App origin placeholder is missing");
 }
 if (!renderedSource.includes(`<base href="${APP_BASE}">`)) {
 	errors.push("absolute MCP App asset base is missing");
 }
 if (!renderedSource.includes('http-equiv="Content-Security-Policy"')) {
 	errors.push("defense-in-depth Content Security Policy is missing");
 }
 if (source.includes("<script>") || source.includes("<style>")) {
 	errors.push("inline JS/CSS remains in the MCP App snapshot template");
 }
 if (
 	!/<script defer src="\.\/assets\/app\.js\?v=[a-f0-9]{16}"><\/script>/.test(
 		source,
 	) ||
 	/<script[^>]+type="module"/.test(source)
 ) {
 	errors.push(
 		"external MCP App template is not using one classic deferred script",
 	);
 }
 if (scriptPaths.length !== 1 || cssPaths.length !== 1) {
 	errors.push(
 		`expected one external JS and one external CSS asset; found ${scriptPaths.length} JS and ${cssPaths.length} CSS`,
 	);
 }
 const expectedAssetPaths = ["assets/app.css", "assets/app.js"];
 if (JSON.stringify(allAssetPaths) !== JSON.stringify(expectedAssetPaths)) {
 	errors.push(
 		`expected only stable MCP App assets ${expectedAssetPaths.join(", ")}; found ${allAssetPaths.join(", ")}`,
 	);
 }
 if (
 	JSON.stringify(
 		versionedAssetReferences.map(({ assetPath }) => assetPath).sort(),
 	) !== JSON.stringify(expectedAssetPaths)
 ) {
 	errors.push("stable MCP App asset URLs are missing content-derived versions");
 }
 if (resourceResponseBytes > MAX_RESOURCE_RESPONSE_BYTES) {
 	errors.push(
 		`resources/read JSON is ${resourceResponseBytes.toLocaleString()} bytes; budget is ${MAX_RESOURCE_RESPONSE_BYTES.toLocaleString()} bytes`,
 	);
 }

 let css = "";
 let javascript = "";
 for (const assetPath of allAssetPaths) {
 	const assetUrl = new URL(
 		`../dist-mcp-apps/interaction/${assetPath}`,
 		import.meta.url,
 	);
 	try {
 		await stat(assetUrl);
 		const asset = await readFile(assetUrl);
 		const expectedVersion = createHash("sha256")
 			.update(asset)
 			.digest("hex")
 			.slice(0, 16);
 		const reference = versionedAssetReferences.find(
 			(candidate) => candidate.assetPath === assetPath,
 		);
 		if (reference?.version !== expectedVersion) {
 			errors.push(`MCP App asset version does not match ${assetPath} contents`);
 		}
 		if (assetPath.endsWith(".css")) css += asset.toString("utf8");
 		if (assetPath.endsWith(".js")) javascript += asset.toString("utf8");
 	} catch {
 		errors.push(`referenced MCP App asset is missing: ${assetPath}`);
 	}
 }
 try {
 	// Compilation as a classic script rejects module-only syntax such as
 	// import.meta, top-level imports/exports, and top-level await.
 	new Function(javascript);
 } catch (error) {
 	errors.push(
 		`external MCP App JavaScript is not classic-script compatible: ${error}`,
 	);
 }
 if (
 	css.includes("/fonts/") ||
 	/url\(\s*(["']?)(?!data:|#)[^)]+\1\s*\)/i.test(css)
 ) {
 	errors.push("unexpected runtime URL remains in MCP App CSS");
 }
 for (const selector of requiredStoredTemplateSelectors) {
 	if (!css.includes(selector)) {
 		errors.push(
 			`stored json_template utility is missing from CSS: ${selector}`,
 		);
 	}
 }

 if (errors.length > 0) {
 	console.error("MCP App bundle check FAILED:\n");
 	for (const error of errors) console.error(`• ${error}`);
 	process.exitCode = 1;
 } else {
 	console.log(
-		`MCP App bundle check passed (${sourceBytes.toLocaleString()} external HTML bytes; ${resourceResponseBytes.toLocaleString()} v10 self-contained resources/read JSON bytes; ${Buffer.byteLength(legacySource).toLocaleString()} packed HTML bytes; classic content-versioned app.js/app.css).`,
+		`MCP App bundle check passed (${sourceBytes.toLocaleString()} external HTML bytes; ${resourceResponseBytes.toLocaleString()} v11 self-contained resources/read JSON bytes; ${Buffer.byteLength(legacySource).toLocaleString()} packed HTML bytes; classic content-versioned app.js/app.css).`,
 	);
 }
