1370				if (!key || key.length > 120) return;
1371				const next = { ...viewStateRef.current, [key]: value };
1372				viewStateRef.current = next;
1373				viewStateRevision.current += 1;
1374				setViewStateValue(next);
1375				if (!app) return;
1376				if (saveStateTimer.current !== null) {
1377					window.clearTimeout(saveStateTimer.current);
1378				}
1379				saveStateTimer.current = window.setTimeout(() => {
1380					saveStateTimer.current = null;
1381					persistSnapshotStateRef.current?.();
1382				}, 250);
1383			},
1384			[app],
1385		);
1386	
1387		const callTool = async (name: string, args: ToolArgs) => {
1388			if (!app) {
1389				if (!isEmbedded) {
1390					console.log("[mcp-app] tools/call", name, args);
1391					setLastResult((last) => ({
1392						isError: false,
1393						seq: (last?.seq ?? 0) + 1,
1394					}));
1395				}
1396				return;
1397			}
1398			try {
1399				const result = await app.callServerTool({
1400					name,
1401					arguments: args,
1402					...(name === "resolve_lobu_approval" && approvalCapability
1403						? { _meta: { "lobu/approval-capability": approvalCapability } }
1404						: {}),
1405				});
1406				if (isStructuredObject(result.structuredContent)) {
1407					const nextData = result.structuredContent as T;
1408					const nextSnapshotCapability = snapshotCapabilityFromMeta(result._meta);
1409					resetResultViewState();
1410					pendingCompatibilityMetadata.current = null;
1411					resultExplicitlyCleared.current = false;
1412					hasAuthoritativeResultAbsence.current = false;
1413					supersededHostIdentity.current =
1414						toolCallId.current === null || toolCallName.current === null
1415							? null
1416							: hostIdentityKey(toolCallId.current, toolCallName.current);
1417					hasDetachedAppResult.current = true;
1418					toolCallId.current = null;
1419					toolCallName.current = name;
1420					setToolName(name);
1421					snapshotCapability.current = nextSnapshotCapability ?? null;
1422					resultCapabilityIdentity.current =
1423						typeof nextSnapshotCapability === "string"
1424							? nextSnapshotCapability
1425							: null;
1426					if (typeof nextSnapshotCapability === "string") {
1427						// This iframe made the call and received the complete replacement
1428						// result, so there is no historical view state to hydrate before its
1429						// first local edit is saved.
1430						snapshotRestoreCompleted.current.add(
1431							JSON.stringify([null, name, nextSnapshotCapability]),
1432						);
1433					}
1434					hasLiveToolOutput.current = true;
1435					hasAuthoritativeResultData.current = true;
1436					hasCurrentLifetimeToolResult.current = true;
1437					authoritativeDataRevision.current += 1;
1438					hasData.current = true;
1439					displayedDataFingerprint.current = resultDataFingerprint(nextData);
1440					displayedData.current = nextData;
1441					displayedResultIdentity.current = nextSnapshotCapability ?? null;
1442					setData(nextData);
1443					setResultUnavailable(false);
1444					persistOpenAiData(
1445						openAiCompatTargets(),
1446						nextData,
1447						nextSnapshotCapability ?? null,
1448					);
1449				}
1450				if (name === "resolve_lobu_approval" && result.isError !== true) {
1451					setApprovalCapability(null);
1452				}
1453				setLastResult((last) => ({
1454					isError: result.isError === true,
1455					seq: (last?.seq ?? 0) + 1,
1456				}));
1457			} catch {
1458				setLastResult((last) => ({
1459					isError: true,
1460					seq: (last?.seq ?? 0) + 1,
1461				}));
1462			}
1463		};
1464	
1465		const openLink = async (href: string) => {
1466			if (!isExternalHttpUrl(href)) {
1467				console.warn("[mcp-app] refused non-HTTP external link");
1468				return;
1469			}
1470			if (!app) {
1471				if (!isEmbedded) console.log("[mcp-app] ui/open-link", href);
1472				return;
1473			}
1474			try {
1475				const result = await app.openLink({ url: href });
1476				if (result.isError) console.warn("[mcp-app] host rejected external link");
1477			} catch {
1478				console.warn("[mcp-app] host rejected external link");
1479			}
1480		};
1481	
1482		return (
1483			<McpAppContext.Provider
1484				value={{
1485					data,
1486					resultUnavailable,
1487					toolName,
1488					viewState,
1489					setViewState,
1490					callTool,
1491					openLink,
1492					lastResult,
1493					allowSpaHostedViews,
1494				}}
1495			>
1496				{children}
1497			</McpAppContext.Provider>
1498		);
1499	}
