274	async function restoreMcpAppResultImpl(
275		args: {
276			tool_call_id?: string | number;
277			snapshot_capability?: string;
278			tool_name?: string;
279		},
280		_env: Env,
281		ctx: ToolContext,
282	) {
283		const sql = getDb();
284		const capabilityIdentity = snapshotIdentity(ctx, args.snapshot_capability);
285		const identity =
286			args.tool_call_id === undefined
287				? null
288				: snapshotIdentity(ctx, args.tool_call_id);
289		let row: SnapshotRow | undefined;
290		if (capabilityIdentity) {
291			const candidates = await sql<SnapshotLookupRow>`
292				SELECT body, tool_name, tool_call_key
293					FROM public.mcp_app_result_snapshots
294					WHERE organization_id = ${capabilityIdentity.organizationId}
295						AND client_id = ${capabilityIdentity.clientId}
296						AND user_id = ${capabilityIdentity.userId}
297						AND conversation_key = ${capabilityIdentity.conversationKey}
298						AND expires_at > now()
299					ORDER BY updated_at DESC, tool_call_key
300					LIMIT ${MCP_APP_RESULT_CONVERSATION_CAP}
301				`;
302			row = candidates.find((candidate) => {
303				const snapshot = parseSnapshot(candidate.body);
304				return snapshot?.bindingKey === capabilityIdentity.toolCallKey;
305			});
306		} else if (args.snapshot_capability !== undefined) {
307			// A supplied capability is a correlation assertion. Fail closed instead of
308			// falling back to a potentially reused host card id when it is invalid.
309			return { found: false, view_state: {} };
310		} else if (identity) {
311			[row] = await sql<SnapshotRow>`
312				SELECT body, tool_name
313				FROM public.mcp_app_result_snapshots
314				WHERE organization_id = ${identity.organizationId}
315					AND client_id = ${identity.clientId}
316					AND user_id = ${identity.userId}
317					AND conversation_key = ${identity.conversationKey}
318					AND tool_call_key = ${identity.toolCallKey}
319					AND expires_at > now()
320			`;
321		}
322		if (!row || (args.tool_name && row.tool_name !== args.tool_name))
323			return { found: false, view_state: {} };
324		const snapshot = parseSnapshot(row.body);
325		if (!snapshot || snapshot.toolName !== row.tool_name) {
326			logger.warn(
327				{ toolName: row.tool_name },
328				"Discarded unreadable MCP App result snapshot",
329			);
330			return { found: false, view_state: {} };
331		}
332		return {
333			found: true,
334			tool_name: snapshot.toolName,
335			data: snapshot.data,
336			view_state: snapshot.viewState,
337		};
338	}
