import { act, render, screen, waitFor } from "@testing-library/react";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

const bridge = vi.hoisted(() => ({
	callServerTool: vi.fn().mockResolvedValue({ isError: false }),
	connect: vi.fn().mockResolvedValue(undefined),
	hostContext: {} as Record<string, unknown>,
	listeners: new Map<string, Set<(params: unknown) => void>>(),
}));

vi.mock("@modelcontextprotocol/ext-apps", () => ({
	App: class {
		addEventListener(name: string, handler: (params: unknown) => void) {
			const handlers = bridge.listeners.get(name) ?? new Set();
			handlers.add(handler);
			bridge.listeners.set(name, handlers);
		}
		removeEventListener(name: string, handler: (params: unknown) => void) {
			bridge.listeners.get(name)?.delete(handler);
		}
		callServerTool = bridge.callServerTool;
		connect = bridge.connect;
		getHostContext() {
			return { theme: "light", ...bridge.hostContext };
		}
		async openLink() { return { isError: false }; }
	},
	PostMessageTransport: class { async close() {} },
}));

const originalParent = Object.getOwnPropertyDescriptor(window, "parent");
const originalOpenAi = Object.getOwnPropertyDescriptor(window, "openai");

describe("review probe", () => {
	beforeEach(() => {
		vi.resetModules();
		vi.clearAllMocks();
		bridge.listeners.clear();
		bridge.hostContext = {};
		bridge.connect.mockResolvedValue(undefined);
	});
	afterEach(() => {
		if (originalParent) Object.defineProperty(window, "parent", originalParent);
		if (originalOpenAi) Object.defineProperty(window, "openai", originalOpenAi);
		else Reflect.deleteProperty(window, "openai");
	});

	it("switches from an expired capability-only card to a different historical host card", async () => {
		const parent = Object.assign(new EventTarget(), { location: { origin: window.location.origin } });
		Object.defineProperty(window, "parent", { configurable: true, value: parent });
		Object.defineProperty(window, "openai", { configurable: true, value: {} });
		bridge.callServerTool.mockImplementation(async (request: { name: string; arguments: Record<string, unknown> }) => {
			if (request.name !== "restore_lobu_app_result") return { isError: false };
			if (request.arguments.snapshot_capability === "expired") {
				return { isError: false, structuredContent: { found: false, view_state: {} } };
			}
			if (request.arguments.tool_call_id === "next-card") {
				return { isError: false, structuredContent: { found: true, tool_name: "query_sql", data: { title: "Next card" }, view_state: {} } };
			}
			return { isError: false, structuredContent: { found: false, view_state: {} } };
		});

		const { Provider, useMcpApp } = await import("./host");
		function Probe() {
			const { data, resultUnavailable } = useMcpApp<{ title: string }>();
			return <span>{resultUnavailable ? "Unavailable" : data?.title ?? "Loading"}</span>;
		}
		render(<Provider devMock={{ title: "Dev" }}><Probe /></Provider>);
		await waitFor(() => expect(bridge.connect).toHaveBeenCalledTimes(1));

		act(() => {
			for (const handler of bridge.listeners.get("toolresult") ?? []) {
				handler({ structuredContent: {}, _meta: { "lobu/mcp-app-snapshot-capability": "expired" } });
			}
		});
		expect(await screen.findByText("Unavailable")).toBeInTheDocument();

		bridge.hostContext = { toolInfo: { id: "next-card", tool: { name: "query_sql" } } };
		act(() => {
			for (const handler of bridge.listeners.get("hostcontextchanged") ?? []) handler({ theme: "light" });
		});

		expect(await screen.findByText("Next card")).toBeInTheDocument();
	});
});

