import { act, render, screen, waitFor } from "@testing-library/react";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

const bridge = vi.hoisted(() => ({ callServerTool: vi.fn(), connect: vi.fn().mockResolvedValue(undefined), hostContext: {} as Record<string, unknown>, listeners: new Map<string, Set<(params: unknown) => void>>() }));
vi.mock("@modelcontextprotocol/ext-apps", () => ({
	App: class {
		addEventListener(name: string, handler: (params: unknown) => void) { const handlers = bridge.listeners.get(name) ?? new Set(); handlers.add(handler); bridge.listeners.set(name, handlers); }
		removeEventListener(name: string, handler: (params: unknown) => void) { bridge.listeners.get(name)?.delete(handler); }
		callServerTool = bridge.callServerTool; connect = bridge.connect;
		getHostContext() { return { theme: "light", ...bridge.hostContext }; }
		async openLink() { return { isError: false }; }
	},
	PostMessageTransport: class { async close() {} },
}));
const originalParent = Object.getOwnPropertyDescriptor(window, "parent");
const originalOpenAi = Object.getOwnPropertyDescriptor(window, "openai");

describe("review probe", () => {
	beforeEach(() => { vi.resetModules(); vi.clearAllMocks(); bridge.listeners.clear(); bridge.hostContext = {}; bridge.connect.mockResolvedValue(undefined); });
	afterEach(() => { if (originalParent) Object.defineProperty(window, "parent", originalParent); if (originalOpenAi) Object.defineProperty(window, "openai", originalOpenAi); else Reflect.deleteProperty(window, "openai"); });
	it("does not reauthorize a terminally missing capability from a delayed metadata-plus-widget echo", async () => {
		const parent = Object.assign(new EventTarget(), { location: { origin: "https://portable-host.example" } });
		Object.defineProperty(window, "parent", { configurable: true, value: parent });
		let restoreCount = 0;
		bridge.callServerTool.mockImplementation(async (request: { name: string }) => {
			if (request.name !== "restore_lobu_app_result") return { isError: false };
			restoreCount += 1;
			return { isError: false, structuredContent: { found: false, view_state: {} } };
		});
		const { Provider, useMcpApp } = await import("./host");
		function Probe() { const { data, resultUnavailable } = useMcpApp<{ title: string }>(); return <span>{data?.title ?? (resultUnavailable ? "Unavailable" : "No result")}</span>; }
		render(<Provider devMock={{ title: "Dev" }}><Probe /></Provider>);
		await waitFor(() => expect(bridge.connect).toHaveBeenCalledTimes(1));
		act(() => { for (const handler of bridge.listeners.get("toolresult") ?? []) handler({ structuredContent: {}, _meta: { "lobu/mcp-app-snapshot-capability": "expired-token" } }); });
		expect(await screen.findByText("Unavailable")).toBeInTheDocument();
		expect(restoreCount).toBe(1);

		act(() => {
			window.dispatchEvent(new CustomEvent("openai:set_globals", { detail: { globals: {
				widgetState: { privateContent: { lobuViewSnapshot: { version: 1, data: { title: "Expired cached card" }, resultIdentity: "expired-token" } } },
				toolResponseMetadata: { mcp_tool_result: { _meta: { "lobu/mcp-app-snapshot-capability": "expired-token" } } },
			} } }));
		});
		await act(() => new Promise((resolve) => setTimeout(resolve, 0)));
		expect(screen.queryByText("Expired cached card")).not.toBeInTheDocument();
		expect(screen.getByText("Unavailable")).toBeInTheDocument();
		expect(restoreCount).toBe(1);
	});
});

